<script setup lang="ts">import { computed, nextTick, ref, watch } from "vue";import { useI18nStore } from "../stores/i18n";import UiDialog from "./ui/UiDialog.vue";const props=defineProps<{text:string;canPrevious:boolean;canNext:boolean;busy?:boolean}>();const emit=defineEmits<{close:[];slice:[direction:"previous"|"next",offset:number]}>();const i18n=useI18nStore();const textarea=ref<HTMLTextAreaElement|null>(null);const offset=ref(Math.max(1,Math.min(props.text.length-1,Math.floor(props.text.length/2))));const before=computed(()=>props.text.slice(0,offset.value).trim());const after=computed(()=>props.text.slice(offset.value).trim());function capture(){const el=textarea.value;if(!el)return;const next=Number(el.selectionStart||0);if(next>0&&next<props.text.length)offset.value=next}function apply(direction:"previous"|"next"){if(offset.value<=0||offset.value>=props.text.length)return;emit('slice',direction,offset.value)}watch(()=>props.text,()=>{offset.value=Math.max(1,Math.min(props.text.length-1,Math.floor(props.text.length/2)));void nextTick(()=>{textarea.value?.focus();textarea.value?.setSelectionRange(offset.value,offset.value)})},{immediate:true});</script><template><UiDialog :open="true" size="xlarge" :title="i18n.t('pdf_corpus.slice_record','Slice record')" :description="i18n.t('pdf_corpus.slice_record_help','Place the caret where this record should begin or end, then move the misplaced text to the neighboring record. Both records remain in review and the operation can be undone.')" :close-label="i18n.t('ui.close','Close')" @close="emit('close')"><label class="slice-label"><span>{{i18n.t('pdf_corpus.slice_point','Slice point')}}</span><textarea ref="textarea" :value="text" readonly aria-describedby="slice-instructions" @click="capture" @keyup="capture"></textarea></label><p id="slice-instructions" class="instructions">{{i18n.t('pdf_corpus.slice_point_help','Click between characters to choose the boundary. The preview below shows what would move.')}}</p><div class="preview-grid"><article><b>{{i18n.t('pdf_corpus.before_slice','Before slice')}}</b><p>{{before||'—'}}</p></article><article><b>{{i18n.t('pdf_corpus.after_slice','After slice')}}</b><p>{{after||'—'}}</p></article></div><template #footer><div class="slice-actions"><button class="btn" type="button" :disabled="busy||!canPrevious||!before||!after" @click="apply('previous')">← {{i18n.t('pdf_corpus.move_before_previous','Move before slice to previous record')}}</button><button class="btn primary" type="button" :disabled="busy||!canNext||!before||!after" @click="apply('next')">{{i18n.t('pdf_corpus.move_after_next','Move after slice to next record')}} →</button></div></template></UiDialog></template><style scoped>.slice-label{display:grid;gap:7px;font-weight:750}.slice-label textarea{width:100%;min-height:260px;resize:vertical;padding:14px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--text);font:16px/1.65 Georgia,serif}.instructions{margin:0;color:var(--muted);font-size:.875rem;line-height:1.5}.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.preview-grid article{border:1px solid var(--line);border-radius:10px;padding:11px;background:var(--soft);min-width:0}.preview-grid p{margin:7px 0 0;max-height:140px;overflow:auto;white-space:pre-wrap;font-size:.875rem;line-height:1.5}.slice-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}:is(button,textarea):focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:720px){.preview-grid{grid-template-columns:1fr}.slice-actions{flex-direction:column;align-items:stretch}}</style>